"""Unit C: Functions and functional programming."""

from __future__ import annotations

from app.services.python_practice.content.build import mcq as M, out as O


def questions() -> list[dict]:
    return [
        O("function-basics", "easy", "What is printed?", "def f(x):\n    x * 2\n\nprint(f(3))", "None", ["6", "3", "SyntaxError"], "Without a return statement a function returns None; the expression x * 2 is computed and discarded."),
        O("function-basics", "medium", "What is printed?", "def stats(a, b):\n    return a + b, a * b\n\ns, p = stats(3, 4)\nprint(s, p, type(stats(1, 1)).__name__)", "7 12 tuple", ["7 12 list", "(7, 12) None tuple", "7 12 int"], "Returning several values returns one tuple, which can be unpacked."),
        O("argument-passing", "easy", "What is printed?", "def power(base, exp=2):\n    return base ** exp\n\nprint(power(3), power(exp=3, base=2), power(2, 5))", "9 8 32", ["9 9 32", "6 8 10", "9 8 10"], "Positional and keyword arguments can be mixed; keywords may appear in any order."),
        O("argument-passing", "medium", "What happens when this code runs?", "def f(a, b):\n    return a - b\n\nprint(f(5, a=1))", "TypeError", ["4", "-4", "SyntaxError"], "5 binds to a positionally and a=1 binds it again: 'got multiple values for argument a' (a TypeError).", exc="TypeError", ),
        O("default-arguments", "medium", "What is printed?", "def add(x, bucket=[]):\n    bucket.append(x)\n    return bucket\n\nadd(1)\nprint(add(2))", "[1, 2]", ["[2]", "[1]", "[]"], "The default list is created once when the function is defined and shared by every call that omits the argument."),
        M("default-arguments", "medium", "What is the standard fix for a mutable default argument?", "Default to None and create the list inside the function when it is None", ["Use a tuple as the default and append to it", "Declare the parameter as global", "Call the function with copy.copy only"], "`def f(x, bucket=None): if bucket is None: bucket = []` creates a fresh list per call."),
        O("args-kwargs", "easy", "What is printed?", "def f(*args, **kwargs):\n    return len(args), sorted(kwargs)\n\nprint(f(1, 2, 3, a=1, b=2))", "(3, ['a', 'b'])", ["(5, [])", "(3, {'a': 1, 'b': 2})", "([1, 2, 3], ['a', 'b'])"], "*args collects extra positional arguments into a tuple and **kwargs collects keyword arguments into a dict (sorted gives its keys)."),
        O("args-kwargs", "medium", "What is printed?", "def f(a, b, c):\n    return a + b * c\n\nvals = [1, 2]\nopts = {'c': 10}\nprint(f(*vals, **opts))", "21", ["TypeError", "30", "13"], "* unpacks the list into positional arguments and ** unpacks the dict into keywords: f(1, 2, c=10) = 1 + 20."),
        O("scope-namespaces", "medium", "What happens when this code runs?", "x = 10\ndef f():\n    print(x)\n    x = 5\n\nf()", "UnboundLocalError", ["10", "5", "NameError"], "Assigning to x anywhere in the function makes x local for the whole function, so the earlier print reads an unassigned local.", exc="UnboundLocalError"),
        M("scope-namespaces", "easy", "What does the LEGB rule describe?", "The order Python searches scopes: Local, Enclosing, Global, Built-in", ["The order modules are imported", "Four kinds of loops in Python", "The lifetime of local objects"], "A name is looked up in the local scope, then enclosing functions, then the module's globals, then built-ins."),
        O("closures", "medium", "What is printed?", "fs = [lambda: i for i in range(3)]\nprint([f() for f in fs])", "[2, 2, 2]", ["[0, 1, 2]", "[3, 3, 3]", "[0, 0, 0]"], "Closures capture the variable i, not its value; after the loop i is 2. Bind it with a default argument (lambda i=i: i) to capture values."),
        O("closures", "medium", "What is printed?", "def counter():\n    n = 0\n    def inc():\n        nonlocal n\n        n += 1\n        return n\n    return inc\n\nc = counter()\nc(); c()\nprint(c(), counter()())", "3 1", ["1 1", "3 3", "UnboundLocalError"], "Each call to counter() creates a separate enclosing n; nonlocal lets inc modify it. c has been called three times."),
        O("lambda", "easy", "What is printed?", "sq = lambda x: x * x\nprint(sq(4), (lambda a, b=2: a + b)(1))", "16 3", ["8 3", "16 2", "4 3"], "A lambda is an anonymous single-expression function and supports default arguments."),
        M("lambda", "medium", "Which is a limitation of lambda in Python?", "The body must be a single expression, so it cannot contain statements", ["It cannot take arguments", "It cannot be passed to other functions", "It cannot return a value"], "Lambdas hold one expression and no statements such as assignments or return; use def for anything larger."),
        O("recursion", "easy", "What is printed?", "def fact(n):\n    return 1 if n <= 1 else n * fact(n - 1)\n\nprint(fact(5))", "120", ["24", "720", "RecursionError"], "5! = 120; the base case n <= 1 stops the recursion."),
        O("recursion", "medium", "What happens when this code runs?", "def f(n):\n    return f(n + 1)\n\nf(0)", "RecursionError", ["An infinite loop that never ends", "MemoryError immediately", "0"], "CPython caps recursion depth (default about 1000) and raises RecursionError; there is no tail-call optimisation.", exc="RecursionError"),
        O("higher-order", "medium", "What is printed?", "def compose(f, g):\n    return lambda x: f(g(x))\n\ninc = lambda x: x + 1\ndbl = lambda x: x * 2\nprint(compose(inc, dbl)(5), compose(dbl, inc)(5))", "11 12", ["12 11", "11 11", "12 12"], "compose(inc, dbl) applies dbl first: 5*2+1 = 11; compose(dbl, inc) applies inc first: (5+1)*2 = 12."),
        M("higher-order", "easy", "What makes a function 'higher-order'?", "It takes functions as arguments or returns a function", ["It uses recursion", "It has more than three parameters", "It is defined at module level"], "Functions are first-class objects, so they can be passed in and returned."),
        O("map-filter-reduce", "easy", "What is printed?", "from functools import reduce\nprint(list(map(str, [1, 2])), list(filter(None, [0, 1, '', 'a'])), reduce(lambda a, b: a * b, [1, 2, 3, 4]))", "['1', '2'] [1, 'a'] 24", ["['1', '2'] [0, 1, '', 'a'] 24", "[1, 2] [1, 'a'] 10", "['1', '2'] [1, 'a'] 10"], "filter(None, ...) keeps truthy items; reduce folds the list with multiplication."),
        O("map-filter-reduce", "medium", "What is printed?", "m = map(lambda x: x * 2, [1, 2, 3])\nprint(list(m), list(m))", "[2, 4, 6] []", ["[2, 4, 6] [2, 4, 6]", "[2, 4, 6] None", "<map object> <map object>"], "map returns a one-shot iterator; the second list(m) finds it exhausted."),
        O("iterators", "medium", "What is printed?", "it = iter([1, 2])\nprint(next(it), next(it), next(it, 'done'))", "1 2 done", ["1 2 StopIteration", "1 2 None", "1 1 1"], "next(it, default) returns the default instead of raising StopIteration."),
        M("iterators", "medium", "What is the difference between an iterable and an iterator?", "An iterable provides __iter__ returning an iterator; an iterator also has __next__ and is consumed as you use it", ["They are the same thing", "An iterator can be indexed; an iterable cannot", "Only lists are iterables"], "A list is iterable (you can iterate it repeatedly); iter(list) returns a one-pass iterator."),
        O("generators", "easy", "What is printed?", "def gen():\n    yield 1\n    yield 2\n\ng = gen()\nprint(next(g), list(g))", "1 [2]", ["1 [1, 2]", "[1, 2] []", "1 [2, None]"], "next(g) consumes the first value; list(g) collects the rest."),
        O("generators", "hard", "What is printed?", "def gen():\n    x = yield 1\n    print('got', x)\n    yield 2\n\ng = gen()\nprint(next(g))\nprint(g.send('hi'))", "1\ngot hi\n2", ["1\n2", "1\ngot None\n2", "got hi\n1\n2"], "send() resumes the generator and makes the paused `yield` expression evaluate to the sent value."),
        O("decorators", "medium", "What is printed?", "def deco(fn):\n    def wrapper(*a):\n        print('before')\n        return fn(*a)\n    return wrapper\n\n@deco\ndef hi(n):\n    return n * 2\n\nprint(hi(4))", "before\n8", ["8\nbefore", "before\nbefore\n8", "8"], "@deco replaces hi with wrapper; the wrapper prints, then calls the original and returns its result."),
        M("decorators", "medium", "Why use functools.wraps inside a decorator?", "It copies the wrapped function's name and docstring onto the wrapper", ["It makes the wrapper run faster", "It prevents the decorator from being applied twice", "It converts the function into a class"], "Without wraps, introspection tools see the wrapper's name and docs rather than the original's."),
        O("type-hints", "medium", "What is printed?", "def f(x: int) -> str:\n    return x\n\nprint(f('abc'), f.__annotations__)", "abc {'x': <class 'int'>, 'return': <class 'str'>}", ["TypeError", "abc {'x': 'int', 'return': 'str'}", "None {}"], "Type hints are not enforced at runtime; tools like mypy check them. The annotations are just stored on the function."),
        M("type-hints", "easy", "In Python 3.10+, how can you write 'an int or None' as a type hint?", "int | None", ["int or None", "Union(int, None) without importing", "int & None"], "PEP 604 allows X | Y in annotations from Python 3.10; earlier versions use typing.Optional[int].", py="3.10+"),
        M("docstrings", "easy", "Where does Python store a function's docstring?", "In the function's __doc__ attribute", ["In a comment table in the .pyc file only", "In f.__comment__", "It is discarded at compile time"], "A string literal as the first statement becomes __doc__, shown by help()."),
        M("docstrings", "medium", "Which is the best design for a function that parses a config value?", "One clear purpose, descriptive name, type hints, a docstring, and raising a specific exception for bad input", ["A long function that also logs, writes files and parses", "A function with a generic name that returns None on every failure", "A function that prints errors and keeps going"], "Small single-purpose functions with clear contracts are easier to test and reuse; silent failures hide bugs."),
        O("global-nonlocal", "medium", "What is printed?", "count = 0\ndef inc():\n    global count\n    count += 1\n\ninc(); inc()\nprint(count)", "2", ["0", "UnboundLocalError", "1"], "`global` makes count refer to the module-level name, so the augmented assignment updates it."),
        O("global-nonlocal", "hard", "What is printed?", "x = 'global'\ndef outer():\n    x = 'enclosing'\n    def inner():\n        nonlocal x\n        x = 'changed'\n    inner()\n    return x\n\nprint(outer(), x)", "changed global", ["changed changed", "enclosing global", "enclosing changed"], "nonlocal rebinds the nearest enclosing function's x, not the module-level one."),
    ]
